function Expt(b: int, n: nat): int
  requires n >= 0
{
  if n == 0 then 1 else b * Expt(b, n - 1)
}

method expt(b: int, n: nat) returns (res: int) 
  ensures res == Expt(b, n)
{
  var i := 1;
  res := 1;
  while i < n + 1
    decreases n - i + 1 // candidate
    invariant 0 <= i // candidate
    invariant i <= n + 1 // candidate
    invariant res == Expt(b, i - 1) // candidate
  {
    res := res * b;
    i := i + 1;
  }
}

// source: https://www.dcc.fc.up.pt/~nam/web/resources/vfs20/DafnyQuickReference.pdf
lemma {:induction a} distributive(x: int, a: nat, b: nat) 
  ensures Expt(x, a) * Expt(x, b) == Expt(x, a + b)

function fib(n: nat): nat
{
	if n == 0 then 0 else
	if n == 1 then 1 else
		fib(n - 1) + fib(n - 2)
}

method ComputeFib(n: nat) returns (b: nat)
	ensures b == fib(n)
{
	var i: int := 1;
	if 0 <= n < 2 { return n; }
	b := 1;
	var c := 1;

	while i < n
	  invariant 0 <= i <= n // candidate
	  invariant b == fib(i) // candidate
	  invariant c == fib(i + 1) // candidate
	  decreases n - i // candidate
	  invariant 0 <= i // candidate
	  invariant i <= n // candidate
	{
		b, c := c, b + c;
		i := i + 1;
	}
}

method Main()
{
	var ret := ComputeFib(5);
}

